import { module, test } from "qunit";
import Group from "client-app/models/group";

module("Unit | Model | group", function () {
  test("messages remain observable when a member is removed", function (assert) {
    const group = Group.create({
      group: true,
      regex: "/timeout/",
      messages: [
        { key: "one", message: "First timeout" },
        { key: "two", message: "Second timeout" },
      ],
    });
    const firstMessage = group.messages[0];

    group.messages.removeObject(firstMessage);

    assert.strictEqual(group.messages.length, 1);
    assert.strictEqual(group.displayMessage, "Second timeout");
  });
});

import { module, test } from "qunit";
import sinon from "sinon";
import Group from "client-app/models/group";
import MessageCollection from "client-app/models/message-collection";

module("Unit | Model | message collection", function () {
  test("showMoreBefore sends known grouping patterns", async function (assert) {
    const collection = MessageCollection.create();
    collection.rows.addObjects([
      { key: "first" },
      { group: true, regex: "/timeout/", row_id: "group-1" },
      { group: true, regex: "/database/", row_id: "group-2" },
    ]);
    const load = sinon.stub(collection, "load").resolves({ messages: [] });

    await collection.showMoreBefore();

    assert.deepEqual(load.firstCall.args, [
      {
        before: "first",
        knownGroups: ["/timeout/", "/database/"],
      },
    ]);
  });

  test("finds the selected message in a replacement group", function (assert) {
    const currentGroup = Group.create({
      group: true,
      regex: "/timeout/",
      messages: [{ key: "one" }, { key: "two" }],
    });
    const replacementGroup = Group.create({
      group: true,
      regex: "/timeout/",
      messages: [{ key: "one" }, { key: "two" }],
    });
    const collection = MessageCollection.create({
      currentRow: currentGroup,
      currentGroupedMessagesPosition: 1,
    });

    assert.strictEqual(collection.findEquivalentMessageIndex(replacementGroup), 1);
  });
});

import { gt } from "@ember/object/computed";
import EmberObject, { computed } from "@ember/object";
import { tracked } from "@glimmer/tracking";
import { ajax } from "client-app/lib/utilities";
import { getRootPath } from "client-app/lib/preload";

export default class Message extends EmberObject {
  @tracked env = null;
  @tracked protected = false;

  MAX_LEN = 200;

  @gt("count", 1) showCount;

  @computed("MAX_LEN", "expanded", "message.length")
  get hasMore() {
    return !this.expanded && this.message.length > this.MAX_LEN;
  }

  @computed("key")
  get shareUrl() {
    return `${getRootPath()}/show/${this.key}`;
  }

  @computed("MAX_LEN", "expanded", "message.length")
  get displayMessage() {
    let message = this.message;

    if (!this.expanded && this.message.length > this.MAX_LEN) {
      message = this.message.substr(0, this.MAX_LEN);
    }
    return message;
  }

  get canSolve() {
    const appVersion = Array.isArray(this.env)
      ? this.env
          .map((e) => e.application_version)
          .filter(Boolean)
          .join("")
      : this.env && this.env.application_version;
    return appVersion && this.backtrace && this.backtrace.length > 0;
  }

  @computed("severity")
  get rowClass() {
    switch (this.severity) {
      case 0:
        return "debug";
      case 1:
        return "info";
      case 2:
        return "warn";
      case 3:
        return "error";
      case 4:
        return "fatal";
      default:
        return "unknown";
    }
  }

  @computed("severity")
  get glyph() {
    switch (this.severity) {
      case 0:
        return "";
      case 1:
        return "";
      case 2:
        return "exclamation-circle";
      case 3:
        return "times-circle";
      case 4:
        return "times-circle";
      default:
        return "question-circle";
    }
  }

  get prefix() {
    return "fas";
  }

  @computed("severity")
  get klass() {
    switch (this.severity) {
      case 0:
        return "";
      case 1:
        return "";
      case 2:
        return "warning";
      case 3:
        return "error";
      case 4:
        return "fatal";
      default:
        return "unknown";
    }
  }

  async fetchEnv() {
    const env = await ajax(`/fetch-env/${this.key}.json`);
    this.set("env", env);
  }

  expand() {
    this.set("expanded", true);
  }

  solve() {
    return ajax(`/solve/${this.key}`, { type: "PUT" });
  }

  destroy() {
    return ajax(`/message/${this.key}`, { type: "DELETE" });
  }

  async protect() {
    await ajax(`/protect/${this.key}`, { type: "PUT" });
    this.set("protected", true);
  }

  async unprotect() {
    await ajax(`/unprotect/${this.key}`, { type: "DELETE" });
    this.set("protected", false);
  }
}

import { A } from "@ember/array";
import { reads } from "@ember/object/computed";
import Message from "client-app/models/message";
import EmberObject, { computed } from "@ember/object";
import { ajax } from "client-app/lib/utilities";

export default class Group extends EmberObject {
  selected = false;
  showCount = true;

  @reads("regex") key;

  @computed("messages.[]")
  get displayMessage() {
    return this.messages[0]?.message;
  }

  init() {
    super.init(...arguments);
    const messages = A(this.messages.map((m) => Message.create(m)));
    this.set("messages", messages);
  }

  @computed
  get glyph() {
    return "clone";
  }

  @computed
  get prefix() {
    return "far";
  }

  solveAll() {
    return ajax("/solve-group", { type: "POST", data: { regex: this.regex } });
  }
}

import { lte } from "@ember/object/computed";
import EmberObject, { computed } from "@ember/object";

export default class PatternItem extends EmberObject {
  isNew = false;
  value = "";
  valueBuffer = "";
  error = null;
  saving = false;
  count = 0;

  @lte("count", 0) zeroCount;

  init() {
    super.init(...arguments);
    this.set("valueBuffer", this.value);
  }

  @computed("value", "valueBuffer")
  get hasBuffer() {
    return this.value !== this.valueBuffer;
  }

  updateValue(newValue) {
    this.setProperties({
      value: newValue,
      valueBuffer: newValue,
    });
  }
}

import { ajax, increaseTitleCount } from "client-app/lib/utilities";
import Message from "client-app/models/message";
import Group from "client-app/models/group";
import { compare } from "@ember/utils";
import EmberObject, { computed } from "@ember/object";
import { A } from "@ember/array";

const BATCH_SIZE = 50;
export const SEVERITIES = ["Debug", "Info", "Warn", "Err", "Fatal"];

export default class MessageCollection extends EmberObject {
  total = 0;
  rows = A();
  currentRow = null;
  currentTab = null;
  currentEnvPosition = 0;
  currentGroupedMessagesPosition = 0;
  search = "";

  @computed(...SEVERITIES.map((s) => `show${s}`))
  get filter() {
    const filter = [];
    SEVERITIES.forEach((severity, index) => {
      if (this[`show${severity}`]) {
        filter.push(index);
      }
    });
    filter.push(5); // always show unknown, rare
    return filter;
  }

  @computed("currentRow", "currentGroupedMessagesPosition")
  get currentMessage() {
    const row = this.currentRow;
    const position = this.currentGroupedMessagesPosition;
    if (row && row.group) {
      return row.messages[position];
    } else {
      return row;
    }
  }

  @computed("filter", "search.length")
  get hideCountInLoadMore() {
    const filter = this.filter;
    return (
      (this.search && this.search.length > 0) || (filter && filter.length < 6)
    );
  }

  @computed("rows.length", "canLoadMore")
  get moreBefore() {
    return this.rows.length >= BATCH_SIZE && this.canLoadMore;
  }

  @computed("total", "rows.length")
  get totalBefore() {
    return this.total - this.rows.length;
  }

  @computed("search")
  get regexSearch() {
    const search = this.search;
    if (search && search.length > 2 && search[0] === "/") {
      const match = search.match(/\/(.*)\/(.*)/);
      if (match && match.length === 3) {
        try {
          return new RegExp(match[1], match[2]);
        } catch (err) {
          // don't care
        }
      }
    }
    return null;
  }

  async solve(message) {
    await message.solve();
    this.reload();
  }

  selectRow(row, opts = {}) {
    const old = this.currentRow;
    if (old) {
      old.set("selected", false);
    }
    row.set("selected", true);
    const currentGroupedMessagesPosition = opts["messageIndex"] || 0;
    const shouldRefresh =
      currentGroupedMessagesPosition === this.currentGroupedMessagesPosition;
    this.setProperties({
      currentRow: row,
      loadingEnv: false,
      currentGroupedMessagesPosition,
      currentEnvPosition: 0,
    });
    if (shouldRefresh) {
      this.notifyPropertyChange("currentGroupedMessagesPosition");
    }
    const forceFetchEnv = this.currentMessage && !this.currentMessage.env;
    this.fetchEnv({ force: forceFetchEnv });
  }

  tabChanged(newTab) {
    this.setProperties({
      currentTab: newTab,
      loadingEnv: false,
    });
    this.fetchEnv();
  }

  groupedMessageChanged(newPosition) {
    this.setProperties({
      currentGroupedMessagesPosition: newPosition,
      currentEnvPosition: 0,
    });
    const forceFetchEnv = this.currentMessage && !this.currentMessage.env;
    this.fetchEnv({ force: forceFetchEnv });
  }

  envChanged(newPosition) {
    this.set("currentEnvPosition", newPosition);
    this.fetchEnv();
  }

  fetchEnv(opts = {}) {
    const message = this.currentMessage;
    if (
      opts["force"] ||
      (message && !message.env && this.currentTab === "env")
    ) {
      this.set("loadingEnv", true);
      return message.fetchEnv().finally(() => this.set("loadingEnv", false));
    }
  }

  findEquivalentMessageIndex(row) {
    let messageIndex = 0;
    if (
      row?.group &&
      this.currentRow?.group &&
      row.key === this.currentRow.key
    ) {
      messageIndex = row.messages.map((message) => message.key).indexOf(this.currentMessage.key);
      messageIndex = Math.max(0, messageIndex);
    }

    return messageIndex;
  }

  updateSelectedRow() {
    const currentKey = this.currentRow?.key;

    if (currentKey && this.rows) {
      const match = this.rows.find((m) => m.key === currentKey);
      if (match) {
        const messageIndex = this.findEquivalentMessageIndex(match);
        this.selectRow(match, { messageIndex });
      } else {
        this.setProperties({
          currentRow: null,
          currentEnvPosition: 0,
          currentGroupedMessagesPosition: 0,
        });
      }
    }
  }

  request(url, settings) {
    return ajax(url, settings);
  }

  async load(opts) {
    opts ||= {};

    const data = {
      filter: this.filter.join("_"),
    };

    if (this.search && this.search.length > 0) {
      data.search = this.search;
      const regexSearch = this.regexSearch;
      if (regexSearch) {
        data.regex_search = "true";
      }
    }

    if (opts.before) {
      data.before = opts.before;
      if (opts.knownGroups) {
        data.known_groups = opts.knownGroups;
      }
    }

    if (opts.after) {
      data.after = opts.after;
    }

    this.set("loading", true);

    try {
      const response = await this.request("/messages.json", {
        data,
        method: "POST",
      });

      // guard against race: ensure the results we're trying to apply
      //                     match the current search terms
      if (compare(response.filter, this.filter) !== 0) {
        return;
      }

      if (compare(response.search, this.search) !== 0) {
        return;
      }

      if (response.messages.length > 0) {
        const newRows = this.toObjects(response.messages);

        if (opts.before) {
          this.rows.unshiftObjects(newRows);
        } else {
          for (const newRow of newRows) {
            for (const row of this.rows) {
              if (row.key !== newRow.key) {
                continue;
              }

              this.rows.removeObject(row);

              if (this.currentRow === row) {
                const messageIndex = this.findEquivalentMessageIndex(newRow);
                this.selectRow(newRow, { messageIndex });
              }
            }
          }

          this.rows.addObjects(newRows);

          if (newRows.length > 0) {
            increaseTitleCount(newRows.length);
          }
        }
      }

      this.set("total", response.total);
      return response;
    } finally {
      this.set("loading", false);
    }
  }

  async reload() {
    this.set("total", 0);
    this.rows.clear();

    const data = await this.load();
    this.updateCanLoadMore(data);
  }

  updateCanLoadMore(data) {
    if (!data) {
      return;
    }

    if (data.messages.length < BATCH_SIZE) {
      this.set("canLoadMore", false);
    } else {
      this.set("canLoadMore", true);
    }
  }

  loadMore() {
    if (this.rows.length === 0) {
      this.load({});
      return;
    }

    const lastLog = this.rows[this.rows.length - 1];
    const lastKey = lastLog.group ? lastLog.row_id : lastLog.key;

    this.load({
      after: lastKey,
    });
  }

  async showMoreBefore() {
    const firstLog = this.rows[0];
    const firstKey = firstLog.group ? firstLog.row_id : firstLog.key;
    const knownGroups = this.rows.filter((row) => row.group).map((row) => row.regex);

    const data = await this.load({
      before: firstKey,
      knownGroups,
    });

    this.updateCanLoadMore(data);
  }

  toObjects(rows) {
    return rows.map((m) => {
      return m.group ? Group.create(m) : Message.create(m);
    });
  }
}

import Application from "client-app/app";
import config from "client-app/config/environment";
import * as QUnit from "qunit";
import { setApplication } from "@ember/test-helpers";
import { setupEmberOnerrorValidation, start as qunitStart } from "ember-qunit";
import { setup } from "qunit-dom";

export function start() {
  setApplication(Application.create(config.APP));

  setup(QUnit.assert);
  setupEmberOnerrorValidation();
  qunitStart();
}
